use std::collections::{BTreeMap, BTreeSet, HashMap};
use std::hash::{BuildHasherDefault, Hasher};

/// A [`ModelId`] carries its own FNV-1a hash, so a map keyed by one takes
/// that hash as it is instead of running `SipHash` over it on every lookup:
/// the registry is looked up on every hook dispatch, which made `SipHash` a
/// quarter of a step.
#[derive(Clone, Copy, Default)]
pub struct PrehashedHasher(u64);

impl Hasher for PrehashedHasher {
    fn finish(&self) -> u64 {
        self.0
    }

    fn write(&mut self, bytes: &[u8]) {
        for &byte in bytes {
            self.0 = (self.0 ^ u64::from(byte)).wrapping_mul(0x0100_0000_01b3);
        }
    }

    fn write_u64(&mut self, value: u64) {
        self.0 ^= value;
    }
}

type IdMap<V> = HashMap<ModelId, V, BuildHasherDefault<PrehashedHasher>>;

/// The move an illusion holds while it is dead and waiting to come back.
const REVIVE_MOVE: &str = "REVIVE_MOVE";

/// The move a creature holds while it is stunned and missing its turn.
const STUNNED_MOVE: &str = "STUNNED";

/// Whether a creature is doomed: it has no more HP left than the Doom it is
/// carrying, and is carrying some.
fn is_doomed(creature: &Creature, doom: &str) -> bool {
    creature
        .powers
        .iter()
        .any(|power| power.model_id.to_string() == doom)
        && creature.current_hp <= creature.power_amount(doom)
}

/// Which half of the HP-loss pass a call runs.
///
/// A damaging call runs the two halves separately because the redirection to a
/// pet sits between them and may hand the second half a different target.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum HpLossPhase {
    BeforeOsty,
    AfterOsty,
}

/// The move a monster carries until something rolls it one, which is what a
/// freshly stood-up monster holds. A pet never has one rolled.
const UNSET_MOVE: &str = "UNSET_MOVE";
